// DTC settlement feed and participant directory. Only the DTC agent may import this module.
// Schemas follow data/DATA_DICTIONARY.md; /data is regenerated by script, never edited by hand.
import "server-only";
import { z } from "zod";
import { DTC_REF, ISIN, PARTICIPANT, dtcTs, id, loadTables, nullable, num, text } from "./core";

export const settlementActivitySchema = z.object({
  dtc_reference: id(DTC_REF),
  event_ts_et: dtcTs(),
  deliverer_participant: id(PARTICIPANT),
  receiver_participant: id(PARTICIPANT),
  isin: id(ISIN),
  quantity: num(),
  settlement_amount: num(),
  transaction_type: z.enum(["DVP"]),
  event: z.enum(["INSTRUCTED", "SETTLED", "PENDING", "DK"]),
  // DK: QTY_MISMATCH, SSI_MISMATCH. PENDING: INSUFFICIENT_POSITION, UNAFFIRMED, HOLD, NET_DEBIT_CAP.
  reason_code: nullable(z.enum(["QTY_MISMATCH", "SSI_MISMATCH", "INSUFFICIENT_POSITION", "UNAFFIRMED", "HOLD", "NET_DEBIT_CAP"])),
});

export const participantSchema = z.object({
  // One INACTIVE legacy row is numbered "7105X"; live participants are always 4 digits.
  participant_number: id(/^\d{4}X?$/),
  participant_name: text(),
  type: z.enum(["CUSTODIAN", "BROKER_DEALER"]),
  id_source: z.enum(["public", "synthetic"]),
  status: z.enum(["ACTIVE", "INACTIVE"]),
});

const schemas = {
  settlement_activity: settlementActivitySchema,
  participants: participantSchema,
};

export type DtcEvent = z.output<typeof settlementActivitySchema>;
export type DtcParticipant = z.output<typeof participantSchema>;
export type DtcData = ReturnType<typeof loadDtc>;

let cache: ReturnType<typeof load> | undefined;
const load = () => loadTables("dtc", schemas);

/** All DTC tables, parsed once and cached in memory. */
export function loadDtc() {
  return (cache ??= load());
}
